package codes.grow.packages.openbao;

import java.util.Optional;

/**
 * A data key generated by transit ({@code transit/datakey/<plaintext|wrapped>/<name>}). The
 * plaintext is never printed.
 *
 * @param ciphertext the data key encrypted with the transit key
 * @param keyVersion transit key version used
 * @param plaintext the data key bytes (only for the {@code plaintext} variant)
 */
public record DataKey(String ciphertext, int keyVersion, Optional<byte[]> plaintext) {
  @Override
  public String toString() {
    return "DataKey{ciphertext="
        + ciphertext
        + ", keyVersion="
        + keyVersion
        + ", plaintext="
        + (plaintext.isPresent() ? "[REDACTED]" : "none")
        + "}";
  }
}
